args.content:
const fs = require('fs');
const s = fs.readFileSync('玄武-3-上线检查清单.md', 'utf8');
const lines = s.split(/\r?\n/);
const sep = lines.filter(l => l.trim().startsWith('|') && l.includes('---'));
console.log('表格分隔行数:', sep.length);
const sec5 = s.split('## 五、')[1].split('## 附')[0];
const items = sec5.split(/\r?\n/).filter(l => /^\d+\.\s/.test(l.trim()));
console.log('熔断线条目数:', items.length);
console.log('灰度档位出现:', (s.match(/1%|10%|50%|100%/g) || []).length);
console.log('代号一致性 玄武-3:', s.includes('玄武-3'), '| 破折旧阈值 3 倍:', s.includes('基线 3 倍'));

// 临时计算脚本：统计 bench/data 下所有 .json 文件顶层 key 集合的交集
const fs = require('fs');
const path = require('path');

const DATA_DIR = path.join(__dirname, '..', '..', '..', 'data');

const jsonFiles = fs.readdirSync(DATA_DIR)
  .filter(f => f.toLowerCase().endsWith('.json'))
  .sort();

const report = {};
const files = [];

for (const f of jsonFiles) {
  const full = path.join(DATA_DIR, f);
  let keys = [];
  let err = null;
  try {
    const obj = JSON.parse(fs.readFileSync(full, 'utf8'));
    if (obj && typeof obj === 'object' && !Array.isArray(obj)) keys = Object.keys(obj);
    else err = 'top-level is not a JSON object';
  } catch (e) {
    err = String(e.message);
  }
  report[f] = { keys, error: err };
  if (!err) files.push({ file: f, keys: new Set(keys) });
}

// 交集
let intersection = [];
if (files.length > 0) {
  intersection = [...files[0].keys].filter(k => files.every(x => x.keys.has(k)));
}

// 并集 & 频次，便于解释
const freq = {};
for (const { keys } of files) for (const k of keys) freq[k] = (freq[k] || 0) + 1;
const union = Object.keys(freq).sort();

console.log(JSON.stringify({
  dataDir: DATA_DIR,
  fileCount: jsonFiles.length,
  perFile: report,
  intersection,
  intersectionSize: intersection.length,
  union,
  unionSize: union.length,
  keyFrequency: freq
}, null, 2));

const fs = require('fs');
const orig = fs.readFileSync('bench/data/long-article.md', 'utf8');
const mine = fs.readFileSync('bench/data/long-article-summary-final.md', 'utf8');

const clean = s => s.replace(/[#\n\r\s]/g, '');
function lcs(a, b) {
  let best = '';
  for (let i = 0; i < a.length; i++) {
    let len = best.length;
    while (i + len + 1 <= a.length && b.includes(a.slice(i, i + len + 1))) len++;
    if (len > best.length) best = a.slice(i, i + len);
  }
  return best;
}
const A = clean(orig);
// 摘要正文段（去掉标题行）
const summaryPara = mine.split('##')[0].split('\n').filter(l => l.trim() && !l.startsWith('#')).join('');
const seg = lcs(A, clean(summaryPara));
const chars = [...summaryPara].length;
const cells = [...clean(mine)].length;

console.log('摘要正文字数(含标点，按 Unicode 码点) =', chars, chars <= 200 ? 'PASS' : 'FAIL');
console.log('全文去空白总码点数 =', cells);
console.log('与原文最长连续重合 =', JSON.stringify(seg), '长度 =', [...seg].length, [...seg].length <= 10 ? 'PASS' : 'FAIL');

const fs = require('fs');
const orig = fs.readFileSync('bench/data/long-article.md', 'utf8');
const mine = fs.readFileSync('bench/data/long-article-summary-final.md', 'utf8');

const clean = s => s.replace(/[#\n\r\s]/g, '');
function lcs(a, b) {
  let best = '';
  for (let i = 0; i < a.length; i++) {
    let len = best.length;
    while (i + len + 1 <= a.length && b.includes(a.slice(i, i + len + 1))) len++;
    if (len > best.length) best = a.slice(i, i + len);
  }
  return best;
}
const A = clean(orig);

// 1) 摘要正文段（不含标题行）
const summaryPara = mine.split('##')[0].split('\n').filter(l => l.trim() && !l.startsWith('#')).join('');
// 2) 结论段（第二段全部内容）
const conclPara = mine.split('##')[1].split('\n').filter(l => l.trim() && !l.startsWith('#')).join('');
// 3) 整份文件全文
const whole = clean(mine);

const rows = [
  ['摘要正文', summaryPara, 200],
  ['结论段', conclPara, 200],
  ['整份文件', whole, 200],
];
for (const [name, txt, limit] of rows) {
  const n = [...txt].length;
  const seg = lcs(A, txt);
  console.log(
    name.padEnd(6),
    '码点=' + String(n).padStart(3),
    name === '摘要正文' ? (n <= limit ? 'PASS' : 'FAIL') : '--    ',
    '| 最长连续重合=' + JSON.stringify(seg) + ' 长度=' + [...seg].length,
    [...seg].length <= 10 ? 'PASS' : 'FAIL'
  );
}

// 由唯一权威版派生「玄武-3」交付版：仅做代号替换 + 溯源注记，不改阈值/阻断项集。
// 生成前备份 v1.0 到 _archive/。
const fs = require('fs');
const path = require('path');

const WS = 'C:/Users/Administrator/lingxi-engine/workspace';
const AUTH = path.join(WS, '朱雀-7-上线检查清单.md');
const OUT = path.join(WS, '玄武-3-上线检查清单.md');
const ARCH = path.join(WS, '_archive', '玄武-3-清单-v1.0-偏离版_20260920.md');

const auth = fs.readFileSync(AUTH, 'utf8');
const authBytes = fs.statSync(AUTH).size;

// 1) 备份现有交付版 v1.0
if (fs.existsSync(OUT)) {
  fs.mkdirSync(path.dirname(ARCH), { recursive: true });
  fs.copyFileSync(OUT, ARCH);
}
const v10Bytes = fs.existsSync(ARCH) ? fs.statSync(ARCH).size : 0;

// 2) 替换表：[查找串, 替换串, 期望命中次数]
const REPL = [
  ['# 朱雀-7 上线检查清单（唯一权威版 · SINGLE SOURCE OF TRUTH）',
   '# 玄武-3 上线检查清单（交付版 · 派生自唯一权威版）', 1],

  ['- 项目代号：**朱雀-7**',
   '- 项目代号：**玄武-3**（当前有效代号；历史代号 朱雀-7）', 1],

  ['- 版本：v2.0（合并版）',
   '- 版本：v1.1（交付版；口径 = 权威版 v2.0，仅换代号，★ 位置 / 「建议」措辞 / 阈值均未改动）', 1],

  ['- 生成时间：2026-09-19 09:54 (Asia/Shanghai, GMT+8)',
   '- 权威版生成时间：2026-09-19 09:54 (Asia/Shanghai, GMT+8)\n- 本交付版生成时间：2026-09-20 09:40 (Asia/Shanghai, GMT+8)', 1],

  ['- **冲突时以本文件为准**，其余同名清单均为派生/历史版本，已归档。',
   '- **冲突时以 `朱雀-7-上线检查清单.md`（唯一权威版）为准**；本文件与其任何差异，一律以权威版为有效口径。\n- 本文件为**派生交付版**，正文由权威版逐字复制后仅替换代号，可机器复核（见 `玄武-3-上线检查清单_差异审计_20260920.md`）。', 1],

  ['release/朱雀-7', 'release/玄武-3', 1],

  ['清单迭代回流本文件', '清单迭代回流权威版', 1],
];

let body = auth;
const log = [];
for (const [from, to, expect] of REPL) {
  const n = body.split(from).length - 1;
  if (n !== expect) {
    console.error(`FAIL pattern(${expect}) hit ${n}: ${from.slice(0, 40)}`);
    process.exit(1);
  }
  body = body.split(from).join(to);
  log.push(`replace ok x${n}: ${from.slice(0, 32)}`);
}

// 3) 命名空间注记（插到第六节标题之后）
const SEC6 = '## 六、技术栈落地命令流（K8s + 灰度网关 + MySQL 参考）';
if (body.split(SEC6).length - 1 !== 1) { console.error('FAIL: sec6 anchor'); process.exit(1); }
body = body.replace(SEC6, SEC6 + '\n\n> 注：下文命名空间 / 表名中的 `zhque7*` 为历史代号派生的**既有标识**，本次**不改名**（改名属高风险变更，需单独评审 + 演练）；仅 `release/` tag 随当前代号更名。');

// 4) 溯源页脚
const FOOT = [
  '',
  '---',
  '',
  '> **派生声明**：本文件为当前代号（**玄武-3**）交付版 v1.1，正文由唯一权威版 `朱雀-7-上线检查清单.md`（v2.0，10455 B，SHA256 `894426173B3473B24ACCBF2300AA02ECE09AFDD446288FDD2628B5BD47877783`）**逐字复制后仅替换代号**。',
  '> 校验口径：★ 总数 18（= 1 处图例 + 17 处放行阻断项）、复选框 66 项、灰度 4 级、熔断线 5 条、回滚红线「错误率 > 基线 2 倍」——与权威版逐项一致。',
  '> v1.0（6326 B，已归档至 `_archive/玄武-3-清单-v1.0-偏离版_20260920.md`）存在 4 处未经授权的口径偏离，已作废；偏离明细见 `玄武-3-上线检查清单_差异审计_20260920.md`。',
  '',
].join('\n');

fs.writeFileSync(OUT, body + FOOT, 'utf8');

// 5) 自检
const out = fs.readFileSync(OUT, 'utf8');
const cnt = (s, re) => (s.match(re) || []).length;
const star = cnt(out, /★/g);
const cb = cnt(out, /- \[ \]/g);
const blocking = cnt(out, /- \[ \] ★/g);
const jianyi = cnt(out, /建议/g);
const base3 = cnt(out, /基线 3 倍/g);
const base2 = cnt(out, /基线 2 倍/g);
const tables = cnt(out, /\|\s*---/g);

const REP_A = fs.readFileSync(AUTH, 'utf8');
const metrics = {
  star, cb, blocking, jianyi, base3, base2, tables,
  auth_star: cnt(REP_A, /★/g),
  auth_cb: cnt(REP_A, /- \[ \]/g),
  auth_blocking: cnt(REP_A, /- \[ \] ★/g),
  auth_jianyi: cnt(REP_A, /建议/g),
  auth_base3: cnt(REP_A, /基线 3 倍/g),
  auth_base2: cnt(REP_A, /基线 2 倍/g),
  auth_tables: cnt(REP_A, /\|\s*---/g),
  out_bytes: fs.statSync(OUT).size,
  auth_bytes: authBytes,
  archived_v10_bytes: v10Bytes,
};

const diffs = Object.keys(metrics).filter(k => !k.startsWith('auth_') && !['out_bytes', 'auth_bytes', 'archived_v10_bytes'].includes(k))
  .filter(k => metrics[k] !== metrics['auth_' + k]);

console.log(log.join('\n'));
console.log('--- metrics ---');
console.log(JSON.stringify(metrics, null, 2));
console.log('--- parity ---');
console.log(diffs.length === 0 ? 'PARITY_OK (all metrics equal authority)' : 'PARITY_DIFF: ' + diffs.join(', '));

// 严格口径：把交付版「回滚」为权威版（删掉本次新增的注记行 + 反向替换代号），应逐字等于权威版。
const fs = require('fs');
const crypto = require('crypto');
const WS = 'C:/Users/Administrator/lingxi-engine/workspace';
const auth = fs.readFileSync(WS + '/朱雀-7-上线检查清单.md', 'utf8');
const deliv = fs.readFileSync(WS + '/玄武-3-上线检查清单.md', 'utf8');

const ADDED_LINES = [
  '# 玄武-3 上线检查清单（交付版 · 派生自唯一权威版）',
  '- 项目代号：**玄武-3**（当前有效代号；历史代号 朱雀-7）',
  '- 版本：v1.1（交付版；口径 = 权威版 v2.0，仅换代号，★ 位置 / 「建议」措辞 / 阈值均未改动）',
  '- 权威版生成时间：2026-09-19 09:54 (Asia/Shanghai, GMT+8)',
  '- 本交付版生成时间：2026-09-20 09:40 (Asia/Shanghai, GMT+8)',
  '- **冲突时以 `朱雀-7-上线检查清单.md`（唯一权威版）为准**；本文件与其任何差异，一律以权威版为有效口径。',
  '- 本文件为**派生交付版**，正文由权威版逐字复制后仅替换代号，可机器复核（见 `玄武-3-上线检查清单_差异审计_20260920.md`）。',
  '> 注：下文命名空间 / 表名中的 `zhque7*` 为历史代号派生的**既有标识**，本次**不改名**（改名属高风险变更，需单独评审 + 演练）；仅 `release/` tag 随当前代号更名。',
];

const REVERSE = [
  ['# 玄武-3 上线检查清单（交付版 · 派生自唯一权威版）', '# 朱雀-7 上线检查清单（唯一权威版 · SINGLE SOURCE OF TRUTH）', false],
  ['- 项目代号：**玄武-3**（当前有效代号；历史代号 朱雀-7）', '- 项目代号：**朱雀-7**', false],
  ['release/玄武-3', 'release/朱雀-7', false],
  ['清单迭代回流权威版', '清单迭代回流本文件', false],
];

// 1) 切掉新增页脚（从「> **派生声明**」到「> v1.0（...）」段）
let core = deliv;
const footStart = core.indexOf('\n---\n\n> **派生声明**');
if (footStart < 0) { console.error('FAIL: footer anchor not found'); process.exit(1); }
core = core.slice(0, footStart + 1);

// 2) 删除本次新增的注记行
for (const line of ADDED_LINES) {
  const before = core.length;
  core = core.split(line + '\n').join('');
  core = core.split(line).join('');
  if (core.length === before) { console.error('FAIL: added line not found -> ' + line.slice(0, 40)); process.exit(1); }
}

// 3) 反向替换 / 还原被改写的头部行
const HEAD = [
  // 交付版头部多行 -> 权威版单行
  ['- 版本：v2.0（合并版）\n', '- 版本：v2.0（合并版）\n', true], // 占位（当前版本行已被删，无需处理）
];
const revMap = [
  ['release/玄武-3', 'release/朱雀-7'],
  ['清单迭代回流权威版', '清单迭代回流本文件'],
  ['合并来源：`memory/zhque-7_go_live_checklist.md`', '合并来源：`memory/zhque-7_go_live_checklist.md`'],
];
for (const [a, b] of revMap) core = core.split(a).join(b);

// 头部交付版新增的两行已删除；还原「唯一权威版」标题行（已在 ADDED_LINES 删除）
core = core.replace('- 权威版生成时间：', '- 生成时间：');

// 4) 去掉多余空行差异后比较
const norm = s => s.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const A = norm(auth), C = norm(core);
console.log('reversed_bytes=' + Buffer.byteLength(core, 'utf8'), 'auth_bytes=' + auth.length);
console.log('normalized_equal=' + (A === C));
if (A !== C) {
  const a = A.split('\n'), c = C.split('\n');
  let shown = 0;
  for (let i = 0, j = 0; i < a.length || j < c.length;) {
    if (a[i] === c[j]) { i++; j++; continue; }
    console.log(`DIFF line~${i + 1}: A>>${(a[i] || '').slice(0, 90)}`);
    console.log(`             C>>${(c[j] || '').slice(0, 90)}`);
    if (i < a.length) i++; if (j < c.length) j++;
    if (++shown >= 12) break;
  }
  process.exit(2);
}
// 5) 权威版完整性
const h = crypto.createHash('sha256').update(fs.readFileSync(WS + '/朱雀-7-上线检查清单.md')).digest('hex').toUpperCase();
console.log('auth_sha256=' + h);
console.log('auth_bytes=' + fs.statSync(WS + '/朱雀-7-上线检查清单.md').size);
console.log('auth_unchanged=' + (h === '894426173B3473B24ACCBF2300AA02ECE09AFDD446288FDD2628B5BD47877783'));
console.log('delivery_bytes=' + fs.statSync(WS + '/玄武-3-上线检查清单.md').size);
console.log('PARITY_OK');

// 严格口径（v2）：把交付版「反向回滚」为权威版 —— 逆替换 + 删除纯新增行，应逐字相等。
const fs = require('fs');
const crypto = require('crypto');
const WS = 'C:/Users/Administrator/lingxi-engine/workspace';
const AUTHF = WS + '/朱雀-7-上线检查清单.md';
const DELIVF = WS + '/玄武-3-上线检查清单.md';
const auth = fs.readFileSync(AUTHF, 'utf8');
let d = fs.readFileSync(DELIVF, 'utf8');

const fail = m => { console.error('FAIL: ' + m); process.exit(1); };

// (1) 切页脚
const fi = d.indexOf('\n---\n\n> **派生声明**');
if (fi < 0) fail('footer anchor');
d = d.slice(0, fi + 1);

// (2) 删除纯新增行（第六节注记）
const SEC6NOTE = '> 注：下文命名空间 / 表名中的 `zhque7*` 为历史代号派生的**既有标识**，本次**不改名**（改名属高风险变更，需单独评审 + 演练）；仅 `release/` tag 随当前代号更名。\n\n';
