const fs = require('fs');
const dir = 'bench/data';
const files = fs.readdirSync(dir).filter(f => f.toLowerCase().endsWith('.json')).sort();
const per = {};
const sets = [];
for (const f of files) {
  const obj = JSON.parse(fs.readFileSync(dir + '/' + f, 'utf8'));
  const keys = Object.keys(obj);
  per[f] = keys;
  sets.push(new Set(keys));
}
const interAll = [...sets.reduce((a, b) => new Set([...a].filter(k => b.has(k))))];
const unionAll = [...new Set(sets.flatMap(s => [...s]))].sort();
const recordFiles = files.filter(f => !f.startsWith('_'));
const recordSets = recordFiles.map(f => new Set(per[f]));
const interRecord = [...recordSets.reduce((a, b) => new Set([...a].filter(k => b.has(k))))];
console.log(JSON.stringify({ files, per, interAll, interRecord, recordFiles, unionAll }, null, 2));

